S = "Hakeem Force Academy"
QS = [
(S, "In which year was the first adhesive postage stamp, the Penny Black, introduced?", ["1840", "1820", "1865", "1900"], 0, "The Penny Black was issued in Britain on 1 May 1840 and was the world's first adhesive postage stamp. It was introduced by the postal reformer Rowland Hill.", "Sindh Dak, issued in 1852 in Sindh, was the first postage stamp of the subcontinent.", [2411]),
(S, "In which year was the company Google founded?", ["1996", "1998", "2001", "2004"], 1, "Google was incorporated by Larry Page and Sergey Brin on 4 September 1998. The search project began earlier in 1996 at Stanford University.", "Candidates often say 1996 because the BackRub research project started that year.", [2370]),
(S, "In which year was WhatsApp founded?", ["2005", "2007", "2009", "2012"], 2, "WhatsApp was founded in 2009 by Jan Koum and Brian Acton. It started as a status-update app and soon became a messaging service.", "Facebook (now Meta) bought WhatsApp in 2014.", [2422]),
(S, "In which year was YouTube founded?", ["2003", "2007", "2009", "2005"], 3, "YouTube was founded in February 2005 by Chad Hurley, Steve Chen and Jawed Karim. The first video was uploaded in April 2005.", "Google bought YouTube in 2006.", [2423]),
(S, "Who is credited with inventing the first compound microscope?", ["Zacharias Janssen", "Galileo Galilei", "Robert Hooke", "Louis Pasteur"], 0, "The Dutch spectacle maker Zacharias Janssen is generally credited with the first compound microscope around 1590. Other inventors are sometimes named.", "Robert Hooke published Micrographia in 1665 and coined the word cell.", [4875]),
(S, "Who invented the telephone?", ["Thomas Edison", "Guglielmo Marconi", "Alexander Graham Bell", "Nikola Tesla"], 2, "Alexander Graham Bell was granted the first US patent for the telephone in 1876. He is credited as its inventor.", "Bell's first successful call was made to his assistant Thomas Watson in 1876.", [4878]),
(S, "Who is generally credited as a co-founder of Twitter (now X) and its first chief executive?", ["Mark Zuckerberg", "Jack Dorsey", "Larry Page", "Jeff Bezos"], 1, "Twitter was founded in 2006 by Jack Dorsey, Noah Glass, Biz Stone and Evan Williams. Jack Dorsey is the best known and was its first CEO.", "Twitter was renamed X in 2023 after it was bought by Elon Musk in 2022.", [1214]),
(S, "Which person led the launch of the iPhone, which Apple introduced in 2007?", ["Bill Gates", "Elon Musk", "Steve Wozniak", "Steve Jobs"], 3, "Steve Jobs, co-founder and then CEO of Apple, unveiled the first iPhone in January 2007. Apple is the company that made it.", "Steve Jobs died in 2011 and Tim Cook became Apple's CEO.", [46, 1228, 4938, 349]),
(S, "What is the commonly quoted length of the Pakistan-Iran border?", ["909 km", "1,200 km", "2,430 km", "523 km"], 0, "The Pakistan-Iran border is commonly given as about 909 km. It separates Balochistan from Iran's Sistan and Baluchestan province.", "Some sources give about 959 km, so figures differ slightly by source.", [3471]),
(S, "What is the capital of Ireland?", ["Belfast", "Cork", "Galway", "Dublin"], 3, "Dublin is the capital and largest city of the Republic of Ireland. It lies on the east coast.", "Belfast is the capital of Northern Ireland, which is part of the United Kingdom.", [921]),
(S, "What is the currency of Ireland?", ["Pound sterling", "Euro", "Krone", "Franc"], 1, "Ireland is a member of the Eurozone and uses the euro. It replaced the Irish pound in 2002.", "The euro notes and coins entered circulation on 1 January 2002.", [3311]),
(S, "Which prophet (AS) was given the ability by Allah to soften and melt iron?", ["Hazrat Sulaiman (AS)", "Hazrat Musa (AS)", "Hazrat Dawood (AS)", "Hazrat Yusuf (AS)"], 2, "The Quran says Allah made iron soft for Hazrat Dawood (AS), so he could make armour from it. He is the prophet who received the Zabur.", "Hazrat Sulaiman (AS) was the son of Hazrat Dawood (AS).", [331, 4628, 230]),
(S, "The followers of Hazrat Isa (AS) are called what?", ["Jews", "Christians", "Zoroastrians", "Buddhists"], 1, "The followers of Hazrat Isa (Jesus) are called Christians. Christianity is the largest religion in the world by followers.", "The Quran calls them Nasara (Nazarenes).", [4837, 1196]),
(S, "Who was the mother of Hazrat Ishaq (AS)?", ["Hazrat Hajra", "Hazrat Maryam", "Hazrat Sarah", "Hazrat Asiya"], 2, "Hazrat Ishaq (AS) was the son of Hazrat Ibrahim (AS) and his wife Hazrat Sarah. He was born when Sarah was very old.", "Hazrat Yaqoob (AS) was the son of Hazrat Ishaq (AS).", [302]),
(S, "Who was the first Muazzin (caller to prayer) of Islam?", ["Hazrat Umar (RA)", "Hazrat Abu Bakr (RA)", "Hazrat Ali (RA)", "Hazrat Bilal (RA)"], 3, "Hazrat Bilal ibn Rabah (RA) was appointed by the Holy Prophet (PBUH) as the first Muazzin in Madina. He was known for his beautiful voice.", "Hazrat Bilal (RA) was originally an Abyssinian slave freed by Hazrat Abu Bakr (RA).", [1259, 133]),
(S, "The M-1 motorway connects Islamabad with which city?", ["Peshawar", "Lahore", "Multan", "Karachi"], 0, "The M-1 (Peshawar-Islamabad Motorway) links Peshawar with Islamabad. It is about 155 km long.", "The M-2 motorway connects Islamabad with Lahore.", [2484]),
(S, "In which Islamic month was Pakistan established in 1947?", ["Muharram", "Shaban", "Rajab", "Ramadan"], 3, "Pakistan came into being on 14 August 1947, which was 27 Ramadan 1366 AH. It was the Night of Power (Laylat al-Qadr) by common belief.", "It was also a Friday, the blessed day of the week.", [2257]),
(S, "What is the currency of Israel?", ["Dinar", "New Israeli Shekel", "Riyal", "Lira"], 1, "Israel's currency is the New Israeli Shekel (ILS). It was introduced in 1985.", "The Israeli currency symbol is the sign for the shekel.", [3314]),
(S, "In which year did the USSR veto a UN Security Council resolution on Kashmir, supporting India?", ["1948", "1971", "1962", "1980"], 2, "On 22 June 1962 the Soviet Union vetoed a Security Council resolution on Kashmir backed by Pakistan. This was one of several Soviet vetoes on the issue.", "The USSR had also used its veto on Kashmir in 1957.", [749]),
(S, "Where is Jabal Tariq (Mount of Tariq) located?", ["Gibraltar", "Cairo", "Baghdad", "Istanbul"], 0, "Jabal Tariq is the Arabic name from which the word Gibraltar comes. It is named after Tariq bin Ziyad, who landed there in 711 AD.", "Tariq bin Ziyad began the Muslim conquest of Spain.", [1094]),
(S, "Which angel is the guardian of the gate of Jannah (Paradise)?", ["Malik", "Israfil", "Ridwan", "Mikail"], 2, "Ridwan is the angel in charge of Jannah according to Islamic belief. Malik is the keeper of Jahannam.", "Jannah is said to have eight gates.", [4248]),
(S, "What is the literal meaning of the Arabic word Jannat?", ["Garden", "Light", "Mountain", "River"], 0, "Jannat comes from the Arabic root meaning to hide or cover. It literally means a garden with dense trees.", "The Quran uses the word Jannah for Paradise.", [3476]),
(S, "What is the currency of Japan?", ["Won", "Yuan", "Baht", "Yen"], 3, "Japan's currency is the yen. Its code is JPY.", "The Bank of Japan issues the yen.", [62]),
(S, "Jeddah is a famous port city of which country?", ["Egypt", "Saudi Arabia", "Oman", "Yemen"], 1, "Jeddah is on the Red Sea coast of Saudi Arabia. It is the main gateway for pilgrims travelling to Makkah.", "Jeddah is the second largest city of Saudi Arabia after Riyadh.", [2535]),
]
